runtime.provision:
set -e
PGPASSWORD="$POSTGRES_ADMIN_PASSWORD" "$STACK_INSTALL_DIR/bin/psql" -h "$STACK_SOCKET_DIR" -p "$STACK_PORT" -U stack_admin -d postgres -X -w -q -v ON_ERROR_STOP=1 -v ECHO=none <<'SQL'
SET log_statement = 'none';
SET log_min_error_statement = 'panic';
SET log_min_duration_statement = -1;
SET log_min_duration_sample = -1;
SET log_transaction_sample_rate = 0;
SET password_encryption = 'scram-sha-256';
REVOKE ALL ON DATABASE postgres, template0, template1 FROM PUBLIC;
\getenv group_password DB_PASSWORD
\getenv group_name STACK_GROUP
SELECT format('CREATE ROLE %I LOGIN', :'group_name')
  WHERE NOT EXISTS (SELECT FROM pg_roles WHERE rolname = :'group_name')\gexec
ALTER ROLE :"group_name" LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS PASSWORD :'group_password';
SELECT format('CREATE DATABASE %I OWNER %I ALLOW_CONNECTIONS false', :'group_name', :'group_name')
  WHERE NOT EXISTS (SELECT FROM pg_database WHERE datname = :'group_name')\gexec
SELECT format('DO $refuse$ BEGIN RAISE EXCEPTION %L; END $refuse$', 'database ' || datname || ' belongs to another owner; inspect existing state')
  FROM pg_database WHERE datname = :'group_name' AND datdba <> (SELECT oid FROM pg_roles WHERE rolname = :'group_name')\gexec
REVOKE CONNECT ON DATABASE :"group_name" FROM PUBLIC;
ALTER DATABASE :"group_name" ALLOW_CONNECTIONS true;
SQL

runtime.database_provision:
set -e
PGPASSWORD="$POSTGRES_ADMIN_PASSWORD" "$STACK_INSTALL_DIR/bin/psql" -h "$STACK_SOCKET_DIR" -p "$STACK_PORT" -U stack_admin -d postgres -X -w -q -v ON_ERROR_STOP=1 -v ECHO=none <<'SQL'
SET log_statement = 'none';
SET log_min_error_statement = 'panic';
SET log_min_duration_statement = -1;
SET log_min_duration_sample = -1;
SET log_transaction_sample_rate = 0;
SET password_encryption = 'scram-sha-256';
\getenv database_password DB_PASSWORD
\getenv database_name STACK_DATABASE
\getenv database_user STACK_DATABASE_USER
SELECT set_config('stack.database_name', :'database_name', false), set_config('stack.database_user', :'database_user', false) \gset
DO $provision$
DECLARE
  database_name text := current_setting('stack.database_name');
  database_user text := current_setting('stack.database_user');
  role_oid oid;
BEGIN
  SELECT oid INTO role_oid FROM pg_roles WHERE rolname = database_user;
  IF role_oid IS NOT NULL AND (
    shobj_description(role_oid, 'pg_authid') IS DISTINCT FROM 'stack:database:' || database_user
    OR EXISTS (SELECT FROM pg_roles WHERE oid = role_oid AND
      (rolsuper OR rolcreatedb OR rolcreaterole OR rolreplication OR rolbypassrls OR NOT rolcanlogin))
    OR EXISTS (SELECT FROM pg_auth_members WHERE roleid = role_oid OR member = role_oid)
  ) THEN
    RAISE EXCEPTION 'database role ownership or privileges conflict; inspect existing state';
  END IF;
  IF EXISTS (SELECT FROM pg_database WHERE datname = database_name AND
    (role_oid IS NULL OR datdba <> role_oid)) THEN
    RAISE EXCEPTION 'database belongs to another owner; inspect existing state';
  END IF;
  IF EXISTS (
    SELECT FROM pg_database AS database_entry,
      LATERAL aclexplode(COALESCE(database_entry.datacl, acldefault('d', database_entry.datdba))) AS access_entry
    WHERE database_entry.datname = database_name
      AND access_entry.grantee <> role_oid
      AND access_entry.grantee <> (SELECT oid FROM pg_roles WHERE rolname = 'stack_admin')
      AND NOT (access_entry.grantee = 0 AND NOT database_entry.datallowconn)
  ) THEN
    RAISE EXCEPTION 'database access grants conflict; inspect existing state';
  END IF;
  IF role_oid IS NULL THEN
    EXECUTE format('CREATE ROLE %I LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS', database_user);
    EXECUTE format('COMMENT ON ROLE %I IS %L', database_user, 'stack:database:' || database_user);
  END IF;
END
$provision$;
ALTER ROLE :"database_user" PASSWORD :'database_password';
REVOKE ALL ON DATABASE postgres, template0, template1 FROM PUBLIC;
SELECT format('CREATE DATABASE %I OWNER %I ALLOW_CONNECTIONS false', :'database_name', :'database_user')
  WHERE NOT EXISTS (SELECT FROM pg_database WHERE datname = :'database_name')\gexec
REVOKE ALL ON DATABASE :"database_name" FROM PUBLIC;
ALTER DATABASE :"database_name" ALLOW_CONNECTIONS true;
SQL
